// Block (composition) — the terms a person agrees to before a step: each term with a required or
// optional tag and a way to read it, an agree-all, and a forward action that stays disabled until
// every required term is checked. A counter, a kiosk, a table order, a terminal's onboarding and a
// dashboard sign-up each draw it, and their term labels drift unless set once.
//
// The terms are data, so their wording is set once per product. Agree-all is a checkbox of its own,
// mixed (indeterminate) while some terms are checked, that checks or clears all of them. Each term's
// read action is an icon Button beside it, named "<term> <viewLabel>", never inside the checkbox's
// label, so pressing the row toggles and the chevron reads.
//
// The terms come as one list (`terms`) or as labelled groups (`groups`), one per party that asks, as
// a carrier's application asks for the service's consents and then the carrier's. A group's label
// names its CheckboxGroup, or, with `hasAgreeAll`, is a checkbox that checks or clears that group.
// Agree-all still covers every term in every group.
//
// The forward action is optional: without `submitLabel` and `onSubmit` there is no action row, and
// the consumer puts the action in a bar of its own (a docked bottom bar), enabling it once every
// required term is in `value`.
//
// It arranges Checkbox, CheckboxGroup, Badge, Separator, Button and BottomActionBar; the look of each
// is theirs. The decline is the bar's outline secondary.
import { ChevronRight } from "../components/icons";
import type { ReactNode, Ref } from "react";
import { Badge } from "../components/Badge";
import { Button } from "../components/Button";
import { Checkbox } from "../components/Checkbox";
import { CheckboxGroup } from "../components/CheckboxGroup";
import { Separator } from "../components/Separator";
import { BottomActionBar } from "./BottomActionBar";
import "./ConsentChecklist.css";

export interface ConsentTerm {
  /** Stable key. */
  id: string;
  /** The term's name, e.g. "개인정보 수집·이용 동의". */
  label: string;
  /** When true, the forward action waits for this term. */
  isRequired?: boolean;
  /** Opens the term's full text. Without it the term has no read Button. */
  onView?: () => void;
}

export interface ConsentGroup {
  /** Stable key. */
  id: string;
  /** The group's name, the party that asks, e.g. "제휴사 동의 항목". */
  label: string;
  /** The group's terms, in the order they show. */
  terms: ConsentTerm[];
  /** When true, the label is a checkbox that checks or clears this group's terms. */
  hasAgreeAll?: boolean;
}

export interface ConsentChecklistProps {
  /**
   * Size of the Buttons. `large` on a customer device.
   *
   * @default "large"
   */
  size?: "small" | "medium" | "large";
  /** The terms, in the order they show. Give this or `groups`. */
  terms?: ConsentTerm[];
  /** The terms in labelled groups, in the order they show. Give this or `terms`. */
  groups?: ConsentGroup[];
  /** The ids checked. */
  value: string[];
  /** Called with the ids checked after each change. */
  onChange: (value: string[]) => void;
  /** Label of the agree-all checkbox, e.g. "전체 동의". Without it there is none. */
  agreeAllLabel?: string;
  /** The tag on a required term, e.g. "필수". */
  requiredLabel: string;
  /** The tag on an optional term, e.g. "선택". */
  optionalLabel: string;
  /** Read after a term's name on its read Button, e.g. "보기" → "개인정보 수집·이용 동의 보기". */
  viewLabel: string;
  /**
   * Label of the forward action, e.g. "동의하고 다음". Without it and `onSubmit` there is no action
   * row, and the consumer draws the action elsewhere.
   */
  submitLabel?: ReactNode;
  /** Called with the ids checked when the forward action is pressed. */
  onSubmit?: (value: string[]) => void;
  /** Label of the decline, e.g. "다음에 하기". Without it, or without the action row, there is none. */
  declineLabel?: ReactNode;
  /** Called when the person declines. */
  onDecline?: () => void;
  /** Accessible name of the terms, e.g. "약관". */
  "aria-label": string;
  /** Accessible name of the action row, e.g. "약관 동의". Distinct from the terms' name. */
  actionsLabel: string;
  /** Additional class (optional). sd-consent-checklist is always preserved. */
  className?: string;
  /** Forwarded to the root element. */
  ref?: Ref<HTMLDivElement>;
}

export function ConsentChecklist({
  size = "large",
  terms,
  groups,
  value,
  onChange,
  agreeAllLabel,
  requiredLabel,
  optionalLabel,
  viewLabel,
  submitLabel,
  onSubmit,
  declineLabel,
  onDecline,
  "aria-label": ariaLabel,
  actionsLabel,
  className,
  ref,
}: ConsentChecklistProps) {
  const all = (groups ?? []).flatMap((g) => g.terms).concat(terms ?? []);
  const ids = all.map((t) => t.id);
  const ready = all.every((t) => !t.isRequired || value.includes(t.id));

  // One term list, the group's or the ungrouped one, named by `name` when no visible label does.
  const list = (items: ConsentTerm[], name: { label?: string; "aria-label"?: string }) => (
    <CheckboxGroup {...name} value={value} onChange={onChange}>
      {items.map((t) => (
        <div key={t.id} className="sd-consent-checklist__term">
          {/* The tag is visible; isRequired is what assistive technology hears. The tag and the
              name are two columns, so a wrapped name hangs on its own start, not under the tag. */}
          <Checkbox value={t.id} isRequired={t.isRequired}>
            <span className="sd-consent-checklist__term-label">
              <Badge>{t.isRequired ? requiredLabel : optionalLabel}</Badge>
              <span>{t.label}</span>
            </span>
          </Checkbox>
          {t.onView && (
            <Button isIconOnly variant="ghost" size={size} aria-label={`${t.label} ${viewLabel}`} onPress={t.onView}>
              <ChevronRight aria-hidden size="1em" />
            </Button>
          )}
        </div>
      ))}
    </CheckboxGroup>
  );

  return (
    <div ref={ref} className={className ? `sd-consent-checklist ${className}` : "sd-consent-checklist"}>
      {agreeAllLabel && (
        <>
          <AgreeAll ids={ids} value={value} onChange={onChange}>
            {agreeAllLabel}
          </AgreeAll>
          <Separator isDecorative />
        </>
      )}
      {groups ? (
        <div role="group" aria-label={ariaLabel} className="sd-consent-checklist__groups">
          {groups.map((g) => (
            <div key={g.id} className="sd-consent-checklist__group">
              {g.hasAgreeAll && (
                <AgreeAll ids={g.terms.map((t) => t.id)} value={value} onChange={onChange}>
                  {g.label}
                </AgreeAll>
              )}
              {list(g.terms, g.hasAgreeAll ? { "aria-label": g.label } : { label: g.label })}
            </div>
          ))}
        </div>
      ) : (
        list(terms ?? [], { "aria-label": ariaLabel })
      )}
      {submitLabel != null && onSubmit && (
        <BottomActionBar
          aria-label={actionsLabel}
          size={size}
          primary={{ label: submitLabel, onPress: () => onSubmit(value), isDisabled: !ready }}
          secondary={declineLabel != null && onDecline ? { label: declineLabel, onPress: onDecline } : undefined}
        />
      )}
    </div>
  );
}

/** A checkbox that checks or clears `ids` within `value`, mixed while only some are checked. */
function AgreeAll({
  ids,
  value,
  onChange,
  children,
}: {
  ids: string[];
  value: string[];
  onChange: (value: string[]) => void;
  children: ReactNode;
}) {
  const all = ids.length > 0 && ids.every((id) => value.includes(id));
  const some = !all && ids.some((id) => value.includes(id));
  return (
    <Checkbox
      isSelected={all}
      isIndeterminate={some}
      onChange={(on) =>
        onChange(on ? [...value.filter((v) => !ids.includes(v)), ...ids] : value.filter((v) => !ids.includes(v)))
      }
    >
      {children}
    </Checkbox>
  );
}

/* Layout only (block-contract.md §3, §5): agree-all, the terms and the action row in a column; each
   term's read Button at the end of its row. Groups part from each other two rungs past their own
   gap (token-contract.md § By relationship, parting). */
.sd-consent-checklist {
  display: flex;
  flex-direction: column;
  gap: var(--sd-space-small);
  inline-size: 100%;
}

.sd-consent-checklist__groups {
  display: flex;
  flex-direction: column;
  gap: var(--sd-space-large);
}

.sd-consent-checklist__group {
  display: flex;
  flex-direction: column;
  gap: var(--sd-space-small);
}

.sd-consent-checklist__term {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sd-space-x-small);
}

/* A term's tag and its name in two columns: the name wraps on its own start line, never under the
   tag. Baseline-aligned, so the tag sits on the name's first line. */
.sd-consent-checklist__term-label {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  column-gap: var(--sd-space-x-small);
  align-items: baseline;
}
